class Order:
    def __init__(self, items):
        self.items = items
    def total(self):
        return sum(p * q for p, q in self.items)
result = Order([(10, 2), (5.5, 4)]).total()

def running_total(xs):
    t = 0
    for x in xs:
        t += x
        yield t
result = list(running_total([3, 1, 4, 1, 5]))

def flatten(x):
    out = []
    for i in x:
        out.extend(flatten(i) if isinstance(i, list) else [i])
    return out
